package workverification;
import java.nio.file.*;import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class RelicExecution {
 static class Loader extends ClassLoader {Map<String,byte[]> defs;Loader(Map<String,byte[]> d){super(RelicExecution.class.getClassLoader());defs=d;}protected synchronized Class<?> loadClass(String n,boolean resolve)throws ClassNotFoundException {Class<?> c=findLoadedClass(n);if(c==null&&defs.containsKey(n)){byte[] b=defs.get(n);c=defineClass(n,b,0,b.length);}if(c==null)c=super.loadClass(n,false);if(resolve)resolveClass(c);return c;}}
 static byte[] trim(byte[] bytes){var c=new ClassNode();new ClassReader(bytes).accept(c,0);c.methods.removeIf(m->!m.name.equals("<init>")&&!m.name.equals("grantOrFlagRelic")&&!m.name.equals("notifyPlayer")&&!m.name.equals("sendOwnershipMessage")&&!m.name.contains("prominence$")&&!m.name.contains("mixinextras"));for(var m:c.methods){if(m.name.equals("notifyPlayer")){m.instructions.clear();m.instructions.add(new InsnNode(Opcodes.RETURN));m.tryCatchBlocks.clear();m.localVariables=null;}if(m.name.equals("sendOwnershipMessage")&&m.desc.equals("(Lnet/minecraft/class_3222;Lnet/minecraft/class_1799;)V")){m.instructions.clear();m.instructions.add(new VarInsnNode(Opcodes.ALOAD,0));m.instructions.add(new VarInsnNode(Opcodes.ALOAD,1));m.instructions.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"fixture/Recorder","send",m.desc,false));m.instructions.add(new InsnNode(Opcodes.RETURN));m.tryCatchBlocks.clear();m.localVariables=null;}else if(m.name.equals("sendOwnershipMessage")){m.instructions.clear();m.instructions.add(new InsnNode(Opcodes.RETURN));m.tryCatchBlocks.clear();m.localVariables=null;}}
 var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 public static void main(String[] args)throws Exception {Map<String,byte[]> d=new HashMap<>();Path root=Path.of(args[0]);try(var s=Files.walk(root)){for(var p:s.filter(x->x.toString().endsWith(".class")).toList())d.put(root.relativize(p).toString().replace(java.io.File.separatorChar,'.').replaceAll("\\.class$",""),Files.readAllBytes(p));}d.put("elocindev.prominent.recovery.RelicRecoveryManager",trim(Files.readAllBytes(Path.of(args[1]))));new Loader(d).loadClass("fixture.Runner").getMethod("run").invoke(null);}
}
